  const ys=[y];for(let cy=h/2+6;cy<=height-h/2-6;cy+=8)ys.push(cy);
  let selected=null,cost=Infinity;
  for(const cx of xs)for(const cy of ys){const d=(cx-x)**2*2+(cy-y)**2;if(d>=cost||placed.some(a=>Math.abs(a.x-cx)<w+6&&Math.abs(a.y-cy)<h+6))continue;selected={x:cx,y:cy};cost=d;}
